<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Meeting Cost Calculator</title>
    <style>
        body {
            background-color: #1a1a1a;
            color: white;
            font-family: Arial, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
        }
        .container {
            background-color: #2a2a2a;
            padding: 30px;
            border-radius: 10px;
            width: 300px;
        }
        h1 {
            text-align: center;
            font-size: 24px;
            margin: 0 0 20px 0;
        }
        .input-group {
            margin-bottom: 15px;
        }
        label {
            display: block;
            font-size: 14px;
            margin-bottom: 5px;
        }
        input[type="number"] {
            width: 100%;
            padding: 8px;
            box-sizing: border-box;
            background-color: #3a3a3a;
            color: white;
            border: 1px solid #555;
            border-radius: 5px;
        }
        .display {
            background-color: #1a1a1a;
            padding: 15px;
            border-radius: 5px;
            margin-bottom: 20px;
            text-align: center;
        }
        .display-label {
            font-size: 12px;
            color: #aaa;
            margin-bottom: 5px;
        }
        .display-value {
            font-size: 48px;
            font-weight: bold;
            color: white;
        }
        .button-group {
            display: flex;
            gap: 10px;
            margin-bottom: 10px;
        }
        button {
            flex: 1;
            padding: 10px;
            background-color: #7c3aed;
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            font-size: 14px;
            font-weight: bold;
        }
        button:hover {
            background-color: #6d28d9;
        }
        button:active {
            background-color: #5b21b6;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Meeting Cost</h1>

        <div class="input-group">
            <label for="people">People:</label>
            <input type="number" id="people" value="6" min="1">
        </div>

        <div class="input-group">
            <label for="rate">Hourly Rate ($):</label>
            <input type="number" id="rate" value="100" min="0">
        </div>

        <div class="display">
            <div class="display-label">Elapsed Time</div>
            <div class="display-value" id="timeDisplay">0:00:00</div>
        </div>

        <div class="display">
            <div class="display-label">Total Cost</div>
            <div class="display-value" id="costDisplay">$0.00</div>
        </div>

        <div class="button-group">
            <button id="startBtn" onclick="startTimer()">Start</button>
            <button id="pauseBtn" onclick="pauseTimer()" disabled>Pause</button>
        </div>

        <button onclick="resetTimer()" style="width: 100%;">Reset</button>
    </div>

    <script>
        let seconds = 0;
        let timerInterval = null;
        let isRunning = false;

        function updateDisplay() {
            const people = parseInt(document.getElementById('people').value) || 0;
            const rate = parseFloat(document.getElementById('rate').value) || 0;

            const hours = seconds / 3600;
            const cost = hours * people * rate;

            const h = Math.floor(seconds / 3600);
            const m = Math.floor((seconds % 3600) / 60);
            const s = seconds % 60;

            document.getElementById('timeDisplay').textContent = 
                `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
            document.getElementById('costDisplay').textContent = `$${cost.toFixed(2)}`;
        }

        function startTimer() {
            if (!isRunning) {
                isRunning = true;
                document.getElementById('startBtn').disabled = true;
                document.getElementById('pauseBtn').disabled = false;
                timerInterval = setInterval(() => {
                    seconds++;
                    updateDisplay();
                }, 1000);
            }
        }

        function pauseTimer() {
            isRunning = false;
            clearInterval(timerInterval);
            document.getElementById('startBtn').disabled = false;
            document.getElementById('pauseBtn').disabled = true;
        }

        function resetTimer() {
            isRunning = false;
            clearInterval(timerInterval);
            seconds = 0;
            document.getElementById('startBtn').disabled = false;
            document.getElementById('pauseBtn').disabled = true;
            updateDisplay();
        }

        document.getElementById('people').addEventListener('change', updateDisplay);
        document.getElementById('rate').addEventListener('change', updateDisplay);

        updateDisplay();
    </script>
</body>
</html>
